//! System-tray callback wiring (open window / open chat / open HW Monitor /
//! open log / open downloads / start / stop / quit).
//! `AppTray` is a separate Slint root that does NOT use `AppState`; Rust pushes
//! its state directly; `server_running` also swaps the tray icon to the
//! green-dotted "running" PNG (both variants generated by build.rs; the binding
//! is in app.slint's `AppTray`), and `chat_ui_enabled` (a copy of
//! `AppState.chat_ui_enabled`, both pushed by `gui::push_tray_status`) disables
//! "Open chat UI" while the running server has no web UI. "Open chat UI",
//! "Open HW Monitor" and "Open log" reach back into `AppState`: they invoke `open_chat`, `open_hw_monitor`
//! and `view_logs`, what the Server rail's buttons fire, so the tray opens the
//! same URL and the SAME `HwWindow` / `LogWindow` (one sampler, one tail;
//! `hw_window::wire`, `log_window::wire`) rather than second ones, and does so
//! without surfacing the configurator window. "Open downloads" does the same
//! with `open_downloads` (the one `DownloadsWindow`, `downloads::wire`). Quit
//! goes through `downloads::request_quit`: it quits at once when no Hugging
//! Face download runs, and otherwise asks in the Downloads window first, so a
//! transfer is never dropped by a stray click and no child outlives the
//! process. Helpers live in the parent `gui` module (`use super::*`).

use super::*;

pub(super) fn wire(app: &AppWindow, tray: &AppTray, state: &Rc<RefCell<State>>) {
    {
        let app_weak = app.as_weak();
        tray.on_open_window(move || {
            if let Some(app) = app_weak.upgrade() {
                // Full activation, not a bare show(): restore from minimized
                // and focus, same path as the single-instance wake.
                activate_window(app);
            }
        });
    }
    {
        let app_weak = app.as_weak();
        tray.on_open_chat(move || {
            if let Some(app) = app_weak.upgrade() {
                app.global::<AppState>().invoke_open_chat();
            }
        });
    }
    {
        let app_weak = app.as_weak();
        tray.on_open_hw_monitor(move || {
            if let Some(app) = app_weak.upgrade() {
                app.global::<AppState>().invoke_open_hw_monitor();
            }
        });
    }
    {
        let app_weak = app.as_weak();
        tray.on_open_log(move || {
            if let Some(app) = app_weak.upgrade() {
                app.global::<AppState>().invoke_view_logs();
            }
        });
    }
    {
        let app_weak = app.as_weak();
        let tray_weak = tray.as_weak();
        tray.on_start_server(move || {
            start_server_async(app_weak.clone(), tray_weak.clone());
        });
    }
    {
        let app_weak = app.as_weak();
        let tray_weak = tray.as_weak();
        tray.on_stop_server(move || {
            stop_server_async(app_weak.clone(), tray_weak.clone());
        });
    }
    {
        let app_weak = app.as_weak();
        tray.on_open_downloads(move || {
            if let Some(app) = app_weak.upgrade() {
                app.global::<AppState>().invoke_open_downloads();
            }
        });
    }
    {
        let app_weak = app.as_weak();
        let state = Rc::downgrade(state);
        tray.on_quit_app(move || {
            match (app_weak.upgrade(), state.upgrade()) {
                // Asks first while a download runs (gui/downloads.rs).
                (Some(app), Some(state)) => downloads::request_quit(&app, &state),
                _ => {
                    slint::quit_event_loop().ok();
                }
            }
        });
    }
}
